import os, subprocess, sys, shutil, tempfile
BIN="/workspace/executable"
def run(style, lines, cwd=None, extra_env=None, argv=None):
    d = cwd or tempfile.mkdtemp(prefix="/tmp/rg/sc/")
    os.makedirs(d, exist_ok=True)
    if style is None:
        p=os.path.join(d,".richstyle")
        if os.path.exists(p): os.remove(p)
    else:
        open(os.path.join(d,".richstyle"),"w").write(style)
    env=dict(os.environ)
    env["RICHGO_LOCAL"]="1"
    env["RICHGO_FORCE_COLOR"]="1"
    env["HOME"]="/tmp/rg/emptyhome"
    env["GOPATH"]="/tmp/rg/emptyhome"
    env.pop("GOROOT",None)
    if extra_env: env.update(extra_env)
    r=subprocess.run([BIN]+(argv or ["testfilter"]), input=lines.encode(), capture_output=True, env=env, cwd=d)
    return r
def esc(b):
    out=[]
    for ch in b:
        if ch==0x1b: out.append("\\x1b")
        elif ch==0x0a: out.append("\\n")
        elif ch==0x09: out.append("\\t")
        elif ch==0x0d: out.append("\\r")
        elif 32<=ch<127: out.append(chr(ch))
        else: out.append("\\x%02x"%ch)
    return "".join(out)
def show(style, lines, label="", **kw):
    r=run(style,lines,**kw)
    print("### %s"%label)
    print("  rc=%d"%r.returncode)
    print("  out=%s"%esc(r.stdout))
    if r.stderr: print("  err=%s"%esc(r.stderr))
    return r
PYEOF
